{"path": "/workspace/repo/app/main.py", "content": "import os
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager

from fastapi import FastAPI

from app.db import init_db
from app.routes import orders, webhook


@asynccontextmanager
async def lifespan(_: FastAPI) -> AsyncIterator[None]:
    init_db()
    yield


def create_app() -> FastAPI:
    application = FastAPI(title="Spokes", version="1.4.0", lifespan=lifespan)
    application.include_router(orders.router)
    application.include_router(webhook.router)

    # Conditionally include test routes for contract tests
    if os.getenv("SHOP_TEST_HOOKS") == "1":
        from app.routes import test
        application.include_router(test.router)

    @application.get("/health")
    def health() -> dict[str, str]:
        return {"status": "ok"}

    # Attach webhook secret to app state for use in webhook routes
    parcelly_webhook_secret = os.getenv("PARCELLY_WEBHOOK_SECRET")
    if parcelly_webhook_secret:
        application.state.parcelly_webhook_secret = parcelly_webhook_secret
    else:
        application.state.parcelly_webhook_secret = None

    return application


app = create_app()"}

