  const partners = new Map();
  const partnersByApiKey = new Map();
  let counter = 0;
  let lastPartnerId = null;

  return {
    create({ name, apiKey, flags = {} }) {
      const key = apiKey ?? generateApiKey();
      if (partnersByApiKey.has(key)) {
        throw new ApiError(409, "API_KEY_TAKEN", "A partner with this API key already exists");
      }
      counter += 1;
      const partner = {
        id: `prt_${counter}`,
        name,
        apiKey: key,
        webhook: null,
        flags: { ...flags },
      };
      partners.set(partner.id, partner);
      partnersByApiKey.set(key, partner);
      lastPartnerId = partner.id;
      return partner;
    },

    get(id) {
      return partners.get(id) ?? null;
    },

    findByApiKey(apiKey) {
      return partnersByApiKey.get(apiKey) ?? null;
    },

    setWebhook(partner, webhook) {
      const target = partner ?? (lastPartnerId !== null ? partners.get(lastPartnerId) : null);
      if (!target) {
        throw new ApiError(400, "PARTNER_NOT_FOUND", "Partner not found for webhook registration");
      }
      target.webhook = { url: webhook.url, secret: webhook.secret };
    },

    reset() {
      partners.clear();
      partnersByApiKey.clear();
      counter = 0;
      lastPartnerId = null;
    },
  };
}"}

